/* OMNILIFE: THE SYNDICATE — dark neon terminal-tycoon theme */
:root {
  --bg: #070a12;
  --panel: #0d1320;
  --panel2: #111a2c;
  --line: #1c2942;
  --ink: #d7e3f4;
  --dim: #7a8db0;
  --acc: #22d3ee;       /* cyan */
  --acc2: #c084fc;      /* violet */
  --lime: #4ade80;
  --red: #f87171;
  --amber: #fbbf24;
  --gold: #facc15;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  background:
    radial-gradient(1100px 500px at 80% -10%, rgba(34, 211, 238, 0.08), transparent 60%),
    radial-gradient(900px 500px at 10% 110%, rgba(192, 132, 252, 0.07), transparent 60%),
    var(--bg);
  color: var(--ink);
  font: 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}
button { cursor: pointer; }
input, select {
  background: #0a1120; border: 1px solid var(--line); color: var(--ink);
  border-radius: 8px; padding: 7px 10px; font: inherit; outline: none; min-width: 0;
}
input:focus { border-color: var(--acc); }
canvas { background: transparent; }

/* ---------- login ---------- */
#login {
  min-height: 100vh; display: grid; place-items: center; padding: 24px;
}
.login-card {
  width: 100%; max-width: 460px; background: linear-gradient(160deg, #0e1626, #0a0f1c);
  border: 1px solid var(--line); border-radius: 18px; padding: 34px;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.55);
}
.logo {
  font: 800 26px/1.1 var(--mono); letter-spacing: 2px; text-transform: uppercase;
  background: linear-gradient(90deg, var(--acc), var(--acc2));
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.logo small { display: block; font: 500 11px/1 var(--mono); letter-spacing: 4px; color: var(--dim); margin-top: 6px; -webkit-text-fill-color: #7a8db0; }
.tagline { color: var(--dim); font-size: 12.5px; margin: 14px 0 22px; line-height: 1.6; }
.field { margin-bottom: 14px; }
.field label { display: block; font-size: 11px; letter-spacing: 1px; text-transform: uppercase; color: var(--dim); margin-bottom: 5px; }
.field input { width: 100%; }
.godHint { display: none; margin-top: 8px; font: 12px var(--mono); color: var(--red); }
.godHint.show { display: block; }
.big {
