input.content:
/* OMNILIFE: THE SYNDICATE — CLASSIC desktop edition (90s window chrome)
 * + fully responsive: bottom tab bar & stacked cards on phones/tablets. */
:root {
  --bg: #0f6b5c;
  --deco: #c9d5c7;
  --face: #d9dcd2;          /* classic dialog face */
  --face2: #e7e9e1;
  --line: #8a907f;
  --dark: #404438;
  --shadow: #f4f6ef;
  --ink: #1d2419;
  --dim: #5d6553;
  --acc: #0b5ea8;           /* classic navy accent */
  --acc2: #6d28a8;
  --lime: #2e7d32;
  --red: #b3261e;
  --amber: #a05f00;
  --gold: #8a6d00;
  --sel: #b5d2ee;
  --title1: #0a246a;
  --title2: #a6caf0;
  --mono: "Lucida Console", "Consolas", "Courier New", monospace;
  --sans: Tahoma, "Segoe UI", Verdana, Geneva, sans-serif;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
html { height: 100%; }
body {
  min-height: 100%;
  color: var(--ink);
  font: 13px/1.45 var(--sans);
  background: var(--deco);
}
button { cursor: pointer; font-family: var(--sans); }
input, select, textarea {
  font: 12px var(--sans);
  background: #fff; color: var(--ink);
  border: 2px groove #e8ead9; border-right-color: var(--dark); border-bottom-color: var(--dark);
  padding: 4px 6px; border-radius: 0; outline: none; min-width: 0;
}
input:focus { border: 2px groove var(--sel); }
canvas { background: #fff; border: 2px groove #e8ead9; }

/* ---------- classic buttons ---------- */
.btn, .chip, .spd, .big {
  border: 2px outset #f4f6ef; border-right-color: var(--dark); border-bottom-color: var(--dark);
  background: var(--face); color: var(--ink);
  border-radius: 0; padding: 5px 12px; font: 600 12px var(--sans); white-space: nowrap;
}
.btn:active, .chip:active, .spd:active, .big:active {
  border: 2px inset #e8ead9;
  background: var(--face2);
}
.btn:hover, .chip:hover { background: var(--face2); }
.btn:disabled { color: var(--dim); text-shadow: 1px 1px 0 #fff; cursor: not-allowed; }
.btn.danger { color: var(--red); font-weight: 700; }
.btn.gold { color: var(--gold); font-weight: 700; }
.chip { font: 700 10.5px var(--mono); padding: 4px 8px; }
.chip.on { background: var(--sel); border-style: inset; }
.spd { font: 700 11px var(--mono); padding: 4px 9px; }
.spd.on { background: var(--sel); border-style: inset; font-weight: 700; }
.big {
  width: 100%; margin-top: 12px; padding: 9px;
  font-weight: 700; letter-spacing: 0.4px;
}

/* ---------- classic window frame ---------- */
.win { border: 2px outset #f4f6ef; background: var(--face); box-shadow: 3px 3px 0 rgba(0,0,0,0.25); }
.win-title {
  display: flex; align-items: center; gap: 8px;
  background: linear-gradient(90deg, var(--title2), var(--title1) 55%, #4b78b5);
  color: #fff; font-weight: 700; font-size: 12px; padding: 4px 8px; letter-spacing: 0.4px;
}
.win-title .sx { margin-left: auto; }
.win-title .dots { display: inline-flex; gap: 3px; }
.win-title .dots i {
  width: 14px; height: 12px; background: var(--face); display: inline-block;
  border: 2px outset #f4f6ef; border-right-color: var(--dark); border-bottom-color: var(--dark);
  color: #000; font: 700 9px/10px var(--mono); text-align: center;
}

/* ---------- login ---------- */
#login { min-height: 100vh; display: grid; place-items: center; padding: 12px; }
.login-card { width: 100%; max-width: 470px; }
.login-body { padding: 18px; }
.logo {
  font: 700 19px/1.25 var(--mono); letter-spacing: 1px;
  color: var(--title1); text-transform: uppercase;
}
.logo small { display: block; font: 500 10.5px var(--mono); letter-spacing: 2px; color: var(--dim); margin-top: 5px; }
.tagline { color: var(--dim); font-size: 12px; margin: 12px 0 16px; line-height: 1.55; }
.field { margin-bottom: 12px; }
.field label { display: block; font-size: 11px; letter-spacing: 0.5px; color: var(--dark); font-weight: 700; margin-bottom: 4px; }
.field input { width: 100%; }
.godHint { display: none; margin-top: 8px; font: 700 11px var(--mono); color: var(--red); }
.godHint.show { display: block; }
.fineprint { margin-top: 14px; font-size: 10.5px; color: var(--dim); }
.legendbar {
  margin-top: 14px; padding: 4px 8px; border: 2px inset #e8ead9; font-family: var(--mono);
  font-size: 10px; color: var(--dim); background: var(--face2);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

/* ---------- app shell ---------- */
#app { display: none; height: 100vh; flex-direction: column; }
#app.on { display: flex; }
#topbar {
  padding: 6px 10px 0; background: var(--face);
  border-bottom: 2px groove #e8ead9; flex-shrink: 0;
}
#topbar .tb-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; min-height: 40px; }
#topbar .logo { font-size: 14px; }
.dot {
  width: 8px; height: 8px; background: var(--lime); display: inline-block;
  margin-right: 6px; border: 1px solid #3a5f27;
}
.stat { display: flex; flex-direction: column; min-width: 74px; }
.stat b { font: 700 13px var(--mono); }
.stat span { font-size: 9px; text-transform: uppercase; letter-spacing: 0.8px; color: var(--dim); }
.heatbar { width: 74px; height: 9px; background: #fff; border: 1px solid var(--dark); margin-top: 3px; }
.heatbar i { display: block; height: 100%; background: linear-gradient(90deg, var(--lime), var(--amber), var(--red)); }
.spacer { flex: 1; }
#speedBox { display: flex; gap: 4px; align-items: center; }
#topbar .statusline {
  margin: 6px -10px 0; padding: 3px 10px; border-top: 1px solid var(--line);
  font: 600 11px var(--mono); color: var(--dark); background: var(--face2);
  display: flex; gap: 16px; white-space: nowrap; overflow-x: auto; scrollbar-width: none;
}
#topbar .statusline::-webkit-scrollbar { display: none; }

#shell { flex: 1; display: flex; min-height: 0; }
#side {
  width: 168px; padding: 8px 6px 14px; border-right: 2px groove #e8ead9;
  background: var(--face); overflow-y: auto; flex-shrink: 0;
}
.nav {
  display: flex; align-items: center; gap: 8px; width: 100%; text-align: left;
  padding: 6px 9px; margin-bottom: 2px; border: 2px outset transparent;
  background: transparent; color: var(--ink); font-size: 12.5px; font-weight: 600;
  border-radius: 0;
}
.nav:hover { background: var(--face2); }
.nav.on { background: var(--sel); border-color: var(--face) var(--dark) var(--dark) var(--dark); border-style: inset; }
.nav .ic { width: 19px; text-align: center; }
.nav .badge { margin-left: auto; font: 700 10px var(--mono); color: #fff; background: var(--red); padding: 0 4px; border: 1px solid var(--dark); }
.nav.on .badge { background: var(--dark); }

#main { flex: 1; overflow-y: auto; padding: 14px; min-width: 0; background: #eef0e6; }

/* ---------- panels ---------- */
.phead {
  border: 2px outset #f4f6ef; background: var(--face); padding: 8px 12px;
  display: flex; align-items: baseline; gap: 12px; margin-bottom: 12px; flex-wrap: wrap;
}
.phead h2 { font: 700 15px var(--mono); letter-spacing: 1px; color: var(--title1); text-transform: uppercase; }
.phead p { color: var(--dim); font-size: 11.5px; max-width: 640px; }
.grid { display: grid; gap: 12px; }
.g2 { grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); }
.g3 { grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); }
.g4 { grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); }
.card {
  background: var(--face); border: 2px outset #f4f6ef;
  border-right-color: var(--dark); border-bottom-color: var(--dark);
  padding: 12px; min-width: 0;
}
.card h3 {
  font: 700 10.5px var(--mono); letter-spacing: 1px; text-transform: uppercase;
  color: var(--dark); margin-bottom: 10px; display: flex; align-items: center; gap: 8px;
  border-bottom: 1px solid var(--line); padding-bottom: 5px;
}
.card h3 .rt { margin-left: auto; font-size: 10px; letter-spacing: 0; text-transform: none; color: var(--dim); }
.kpi-card { padding: 10px 12px; }
.kpi-card b { font: 700 17px var(--mono); display: block; }
.kpi-card span { color: var(--dim); font-size: 10px; text-transform: uppercase; letter-spacing: 1px; }
.kpi-card b.up { color: var(--lime); }
.kpi-card b.down { color: var(--red); }
.row { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.row + .row { margin-top: 8px; }
.mono { font-family: var(--mono); }
.dim { color: var(--dim); }
.up { color: var(--lime); }
.down { color: var(--red); }
.warn { color: var(--amber); }
.pill {
  display: inline-block; padding: 2px 7px; font: 600 10.5px var(--mono);
  border: 1px solid var(--line); color: var(--dark); background: var(--face2); letter-spacing: 0.3px;
}
.pill.g { color: var(--lime); border-color: var(--lime); }
.pill.r { color: var(--red); border-color: var(--red); }
.pill.y { color: var(--amber); border-color: var(--amber); }
.pill.c { color: var(--acc); border-color: var(--acc); }
.pill.v { color: var(--acc2); border-color: var(--acc2); }

table { width: 100%; border-collapse: collapse; font-size: 12px; }
th {
  text-align: left; color: var(--face2); font: 700 10px var(--mono); text-transform: uppercase;
  letter-spacing: 0.6px; padding: 5px 7px; background: var(--dark); border: 1px solid #2a2e24;
  position: sticky; top: 0;
}
td { padding: 6px 7px; border: 1px solid var(--line); vertical-align: middle; background: #fff; }
tr:nth-child(even) td { background: var(--face2); }
tr:hover td { background: var(--sel); }
tr.sel td { background: var(--sel); font-weight: 700; }
td .sym { font: 700 11.5px var(--mono); color: var(--acc); }
.sc { max-height: 320px; overflow: auto; border: 2px inset #e8ead9; background: #fff; }

.meter { height: 12px; background: #fff; border: 1px solid var(--dark); margin-top: 6px; }
.meter i { display: block; height: 100%; }
.meter i.c { background: #4b78b5; }
.meter i.g { background: var(--lime); }
.meter i.a { background: var(--amber); }
.meter i.r { background: var(--red); }
.meter i.v { background: var(--acc2); }

.feed { display: flex; flex-direction: column; gap: 6px; }
.post {
  border-left: 3px solid var(--line); padding: 5px 9px; font-size: 12px;
  background: #fff; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line);
}
.post b { font: 700 10.5px var(--mono); color: var(--acc2); }
.post.market { border-left-color: var(--acc); }
.post.scandal { border-left-color: var(--red); }
.post.scandal b { color: var(--red); }
.post .t { color: var(--dim); font: 600 10px var(--mono); margin-right: 6px; }

.log { font: 11.5px var(--mono); line-height: 1.65; max-height: 300px; overflow-y: auto; border: 2px inset #e8ead9; background: #fff; padding: 6px; }
.log div { border-bottom: 1px dotted var(--line); padding: 2px 0; }
.log .t { color: var(--dim); margin-right: 8px; font-size: 10px; }

/* terminal: classic DOS console */
.term {
  background: #000; color: #b9f2c8; border: 2px inset #e8ead9;
  padding: 12px; font: 12px/1.6 var(--mono); min-height: 280px;
  display: flex; flex-direction: column; box-shadow: none;
}
.term .out { white-space: pre-wrap; flex: 1; overflow-y: auto; max-height: 360px; }
.term .out .cmdline { color: #fff; }
.term .out .err { color: var(--red); }
.term form { display: flex; gap: 6px; margin-top: 10px; }
.term input { flex: 1; background: #000; color: #b9f2c8; font-family: var(--mono); border: 2px groove #4c6b52; }
.term .btn { background: #d9dcd2; }

/* toasts */
#toasts { position: fixed; right: 12px; bottom: 12px; display: flex; flex-direction: column; gap: 6px; z-index: 99; max-width: 340px; }
.toast {
  background: var(--face); border: 2px outset #f4f6ef; border-left: 4px solid var(--acc);
  padding: 8px 12px; font-size: 12px; opacity: 0; transform: translateX(16px);
  transition: all 0.22s; box-shadow: 3px 3px 0 rgba(0, 0, 0, 0.25);
}
.toast.show { opacity: 1; transform: none; }
.toast.ok { border-left-color: var(--lime); }
.toast.bad { border-left-color: var(--red); }
.toast.warn { border-left-color: var(--amber); }

.bigflow { font: 800 26px var(--mono); letter-spacing: 0.5px; color: var(--title1); }
.spark { width: 100%; height: 44px; }
.chartBig { width: 100%; height: 220px; }
.selgrad { background: var(--sel); border-color: #6f97c4; }
.center { text-align: center; }
.opnote { font-size: 10.5px; color: var(--dim); margin-top: 8px; }
.risk { font: 700 11px var(--mono); }
.blink { animation: pulse 1.2s infinite; }
@keyframes pulse { 50% { opacity: 0.45; } }

/* ============ RESPONSIVE: phones & tablets ============ */
@media (max-width: 950px) {
  #side .nav span { display: none; } /* icon-only rail on tablets */
  #side { width: 56px; }
}
@media (max-width: 720px) {
  body { font-size: 13px; }
  #app.on { display: flex; height: 100dvh; }
  /* topbar: two stacked rows */
  #topbar .tb-row { gap: 10px; }
  .stat { min-width: 0; flex: 1 1 30%; }
  .stat b { font-size: 12.5px; }
  .stat:nth-child(4) { display: inline-flex; } /* keep heat visible */
  #speedBox .spd { padding: 8px 10px; }
  /* side rail -> fixed bottom tab bar */
  #shell { flex-direction: column; }
  #side {
    order: 2; width: 100%; display: flex; overflow-x: auto; overflow-y: hidden;
    border-right: 0; border-top: 2px groove #e8ead9;
    padding: 6px 8px calc(6px + env(safe-area-inset-bottom, 0px));
    background: var(--face);
  }
  #main { order: 1; height: auto; flex: 1; padding: 10px; }
  .nav, #side .nav span {
    display: inline-flex;
  }
  #side .nav {
    flex: 0 0 auto; flex-direction: column; gap: 2px; min-width: 58px;
    padding: 7px 4px; font-size: 9.5px; text-align: center; justify-content: center;
  }
  #side .nav .ic { font-size: 17px; width: auto; }
  #side .nav span { display: block; white-space: nowrap; }
  .nav .badge { margin-left: 4px; }
  /* cards stack */
  .grid { gap: 10px; }
  .g2, .g3, .g4 { grid-template-columns: 1fr; }
  .card { padding: 10px; }
  .phead { padding: 7px 10px; }
  .phead h2 { font-size: 13px; }
  .bigflow { font-size: 20px; }
  /* touch targets */
  .btn { padding: 9px 13px; }
  .chip { padding: 7px 9px; }
  input, select { padding: 8px 8px; font-size: 13px; }
  td, th { padding: 7px 6px; }
  #toasts { left: 12px; right: 12px; max-width: none; bottom: calc(72px + env(safe-area-inset-bottom, 0px)); }
  .term .out { max-height: 44vh; }
  .chartBig { height: 170px; }
  .sc { max-height: 240px; }
  .row { --gap: 6px; }
  .row .btn, .row .chip { flex: 1 1 auto; text-align: center; }
}
@media (max-width: 380px) {
  .stat b { font-size: 11px; }
  #topbar .logo { display: none; }
}

