  if (pos) {
    const rows = s.tokens.filter((x) => (P(s).tok[x.sym] || 0) > 1e-9).map((x) => {
      const q = P(s).tok[x.sym];
      const v = q * price(x);
      const b = UC.pos[x.sym];
      const cost = b ? b.c * Math.min(1, q / Math.max(1e-9, b.q)) : 0;
      const pl = v - cost;
      return `<a class="row-item" href="#" data-act="sel:${x.sym}" data-nav><span class="sym mono">${x.sym}</span><span class="mono">${cfmt(q)}</span><span class="mono">${fmt(v)}</span><span class="mono ${pl >= 0 ? 'up' : 'down'}">${b ? (pl >= 0 ? '+' : '') + fmt(pl) : 'ok'}</span></a>`;
    }).join('');
    put(pos, rows || emptyB('No coin positions yet.'));
  }
  tradePrev(s);
  drawAll();
}

