    document.querySelectorAll('.tip.open').forEach((x) => { if (x !== tip) x.classList.remove('open'); });
    if (tip) tip.classList.toggle('open');
  });
  window.addEventListener('omni-noti', () => { if (S) renderTop(S); });
}
